/**
 * Input только до cutoff: известные планы, регулярности, категории и полнота в состоянии на cutoff; история для residual calibration не содержит операций после cutoff. calibrationOrigins содержит отдельные входы исторических origins; результат оцениваемых 30 дней не может попасть в их features.
 */
export interface ForecastSnapshot {
  snapshotId: Id;
  companyId: Id;
  accountId: Id;
  asOfDate: Date;
  /** @minimum 0 */
  inputDataVersion: number;
  /** @maxLength 100 */
  algorithmVersion: string;
  settings: ForecastSettings;
  scope: ForecastScope;
  startBalance: Money;
  startBalanceDate: Date;
  historyFrom: Date;
  dailyHistory: DailyActualRs[];
  payments: SnapshotPayment[];
  knownPlans: ExpectedPaymentRs[];
  recurringPatterns: RecurringPatternRs[];
  completeRanges: CompletenessRangeRs[];
  /** Зрелые исторические origins, подготовленные Orchestrator для калибровки риска. Только input на cutoff и outcomes для scoring. Пустой массив означает отсутствие калибровки, а не восстановление прошлого из текущих правок. */
  calibrationOrigins: CalibrationOriginSnapshot[];
  /** @pattern ^[a-f0-9]{64}$ */
  fingerprint: string;
}

export type CalibrationOriginSnapshotInputAllOf = {
  /**
   * Вложенная калибровка запрещена; origin считается точечной моделью без рекурсивного bootstrap.
   * @maxItems 0
   */
  calibrationOrigins?: unknown[];
};

export type CalibrationOriginSnapshotInput = ForecastSnapshot & CalibrationOriginSnapshotInputAllOf;

/**
 * Один зрелый исторический origin для калибровки. input.asOfDate — cutoff origin, input.asOfDate+30≤asOfDate внешнего snapshot. input содержит только состояние, известное на cutoff: совпадают companyId/accountId/algorithmVersion, settings.windowWeeks и правила категоризации той эпохи; поздние USER overrides, планы и регулярности не переносятся. input.calibrationOrigins обязан быть пустым. actualDays (ровно 30 полных дней origin+1…origin+30) и actualPayments тех же дней служат только scoring ошибок и никогда не передаются как features. Если корректное состояние origin восстановить нельзя, origin не включается; при нехватке origins probability=null, а не утёкшая оценка.
 */
export interface CalibrationOriginSnapshot {
  input: CalibrationOriginSnapshotInput;
  /**
   * @minItems 30
   * @maxItems 30
   */
  actualDays: DailyActualRs[];
  actualPayments: SnapshotPayment[];
}

